import{_ as o,o as i,a as r,ag as t}from"./chunks/framework.Do1Zayaf.js";const p=JSON.parse('{"title":"Server-Side Keyed Joins in Roxie","description":"","frontmatter":{},"headers":[],"relativePath":"aidoc/roxie-kb/keyed-joins.md","filePath":"aidoc/roxie-kb/keyed-joins.md","lastUpdated":1779520499000}'),n={name:"aidoc/roxie-kb/keyed-joins.md"};function a(d,e,c,s,l,u){return i(),r("div",null,e[0]||(e[0]=[t('<h1 id="server-side-keyed-joins-in-roxie" tabindex="-1">Server-Side Keyed Joins in Roxie <a class="header-anchor" href="#server-side-keyed-joins-in-roxie" aria-label="Permalink to &quot;Server-Side Keyed Joins in Roxie&quot;">​</a></h1><h2 id="overview" tabindex="-1">Overview <a class="header-anchor" href="#overview" aria-label="Permalink to &quot;Overview&quot;">​</a></h2><p>This document covers the architectural and code-level details of server-side keyed joins, specifically focusing on <strong>Half Keyed Joins</strong>. The primary implementation resides in <code>roxie/ccd/ccdserver.cpp</code>.</p><h3 id="core-classes" tabindex="-1">Core Classes <a class="header-anchor" href="#core-classes" aria-label="Permalink to &quot;Core Classes&quot;">​</a></h3><ul><li><code>CRoxieServerKeyedJoinBase</code> (<code>roxie/ccd/ccdserver.cpp</code>): The base class handling data lifecycle, group aggregation (<code>CJoinGroup</code>), limits (e.g., <code>abortLimit</code>, <code>keepLimit</code>), and transformation handling (<code>doJoinGroup</code>, <code>doTransform</code>).</li><li><code>CRoxieServerHalfKeyedJoinActivity</code> (<code>roxie/ccd/ccdserver.cpp</code>): Inherits from <code>CRoxieServerKeyedJoinBase</code>. Bypasses data file disk fetches because all required fields are present within the matched index payload (<code>!helper-&gt;diskAccessRequired()</code>).</li></ul><h2 id="_1-existing-optimizations-for-half-keyed-joins" tabindex="-1">1. Existing Optimizations for Half Keyed Joins <a class="header-anchor" href="#_1-existing-optimizations-for-half-keyed-joins" aria-label="Permalink to &quot;1. Existing Optimizations for Half Keyed Joins&quot;">​</a></h2><ul><li><strong>Blocked Memory Allocation (<code>roxiemem::RHFblocked</code>)</strong>: <ul><li>Because records (like <code>CJoinGroup</code> and intermediate index fields) are constructed serially by the puller thread, the classes instantiate their allocators (e.g., <code>joinGroupAllocator</code> and <code>indexReadAllocator</code>) with the <code>RHFblocked</code> flag. This avoids hitting <code>roxiemem</code> global locks/critical sections repeatedly.</li></ul></li><li><strong>Simple Mode Fast Path (<code>isSimple</code>)</strong>: <ul><li>In locally-optimized or partitioned layouts, <code>CRoxieServerHalfKeyedJoinActivity</code> sets <code>isSimple = true</code>. When enabled, matched records eagerly <code>enqueue()</code> onto <code>remote.injected</code> queues rather than dynamically building large compound <code>CRowArrayMessageResult</code> messages.</li></ul></li><li><strong>TopLevelKey (TLK) Distributed Hashing</strong>: <ul><li>In <code>CRoxieServerHalfKeyedJoinActivity::processRow</code>, it evaluates <code>thisKey-&gt;isTopLevelKey()</code>. If distributed, it quickly extracts the partition (<code>tlk-&gt;getPartition()</code> or <code>extractFpos()</code>) and copies lookups directly to <code>remote.getMem</code> to ship out to remote worker parts efficiently, rather than resolving locally.</li></ul></li><li><strong>Preloading</strong>: <ul><li>Takes advantage of <code>keyedJoinPreload</code> to bootstrap the index lookups without waiting for downstream pulling.</li></ul></li></ul><h2 id="_2-intra-query-contention-single-query-bottlenecks" tabindex="-1">2. Intra-Query Contention (Single Query Bottlenecks) <a class="header-anchor" href="#_2-intra-query-contention-single-query-bottlenecks" aria-label="Permalink to &quot;2. Intra-Query Contention (Single Query Bottlenecks)&quot;">​</a></h2><ul><li><strong>The <code>groupsCrit</code> Critical Section (<code>CRoxieServerKeyedJoinBase</code>)</strong>: <ul><li>The most glaring contention inside a single executing query involves <code>CriticalBlock c(groupsCrit)</code> in <code>processCompletedGroups()</code>.</li><li><code>processCompletedGroups()</code> holds this lock while iterating through <code>groups.dequeue()</code> and heavily processing <code>doJoinGroup(head)</code>.</li><li><code>doJoinGroup</code> encapsulates the user-defined <code>helper.transform(...)</code> and <code>remote.addResult</code>, mapping the extracted keys into row formats.</li><li><em>Concurrency Fault</em>: <code>processCompletedGroups()</code> is frequently triggered asynchronously via <code>noteEndReceived()</code> (when remote workers finish answering the index sub-read). Because it stalls under <code>groupsCrit</code>, it blocks the main puller thread from instantiating new groups via <code>createJoinGroup(const void *row)</code>, creating severe pipeline stalls during high-fanout index matches.</li></ul></li></ul><h2 id="_3-inter-query-contention-multiple-concurrent-queries" tabindex="-1">3. Inter-Query Contention (Multiple Concurrent Queries) <a class="header-anchor" href="#_3-inter-query-contention-multiple-concurrent-queries" aria-label="Permalink to &quot;3. Inter-Query Contention (Multiple Concurrent Queries)&quot;">​</a></h2><ul><li><strong>JHTree Node Cache Contention (<code>CTreeCache</code>)</strong>: <ul><li>While <code>CRoxieServerHalfKeyedJoinActivity</code> creates an isolated <code>tlk</code> (<code>IKeyManager</code>) instance per query, the underlying <code>IKeyIndex</code> objects and JHTree node layouts are shared globally across queries.</li><li>In heavy load scenarios, multiple concurrent queries performing complex Half Keyed Joins against the same physical indices repeatedly contend on internal JHTree node read locks/cache locks when fetching blocks (since half keyed joins often read many internal branches of indexes).</li></ul></li><li><strong>Reference Counting on Shared Metadata</strong>: <ul><li>Concurrent instances leverage the exact same immutable <code>IResolvedFile</code> (<code>varFileInfo</code>) and <code>ITranslatorSet</code>. Any hidden dynamic allocations or shared atomic reference counters hit simultaneously during <code>tlk-&gt;setKey(...)</code> loop operations (e.g. switching key parts) can introduce false sharing.</li></ul></li></ul>',11)]))}const g=o(n,[["render",a]]);export{p as __pageData,g as default};
